insert into interview.frameworks (slug, name, category, summary, when_to_use, steps, worked_example, common_mistakes, sort_order, status)
values ($c$why-medicine-meif$c$, $c$Why Medicine: Motivation → Evidence → Insight → Fit$c$, $c$structure$c$::interview.framework_category, $c$A four-part structure for 'Why medicine?' and 'Why this school?' that moves you beyond 'I want to help people' by grounding motivation in specific experience, showing a realistic understanding of the job, and linking it to who you are.$c$, $c$Motivation questions: why medicine, why not nursing or research, why this university, what you would bring, where you see yourself. Keep it to about 90 seconds unless invited to go deeper.$c$, $c$[{"title":"Motivation","detail":"One or two genuine drivers, stated specifically: the combination of science and people, the responsibility of decision-making under uncertainty, the long-term relationship with patients. Avoid clichés unless you immediately make them concrete."},{"title":"Evidence","detail":"A specific moment that tested or confirmed that motivation — something you saw, did or read. One vivid example beats a list of placements."},{"title":"Insight","detail":"Show you understand the reality: the demands, uncertainty, emotional load, and what distinguishes the doctor's role from others in the team. Mentioning the downsides — and why you still want it — is what makes an answer credible."},{"title":"Fit","detail":"Connect it to you: qualities you have shown that suit the work, and (for 'why this school') specific features of the course that suit how you learn. End on a forward-looking line."}]$c$::jsonb, $c$Motivation: 'I'm drawn to medicine because it combines scientific problem-solving with responsibility for real people.' Evidence: 'Shadowing on a stroke ward, I watched a registrar explain to a family why their father could not safely swallow — the science was the easy part; the conversation was the skill.' Insight: 'I also saw the pressure: a busy list, an unsettled family, a decision made with incomplete information. That didn't put me off, but it made clear the job is about judgement under uncertainty, not just knowing things.' Fit: 'Running a weekly homework club taught me I enjoy explaining things patiently and adapting to the person in front of me, which is why this path suits me.'$c$, $c$["Opening with 'I've always wanted to be a doctor' or a family story with no reflection.","Listing work experience instead of drawing one insight from it.","Describing reasons that apply equally to nursing, physiotherapy or pharmacy without saying why doctor specifically.","Sounding rehearsed — memorise the structure and examples, not the sentences."]$c$::jsonb, 2, 'published')
