insert into interview.reading_item_categories (reading_item_id, category_id) values ((select id from interview.reading_items where slug = $c$gmc-good-medical-practice$c$), (select id from interview.categories where slug = $c$nhs-current-affairs$c$));
insert into interview.reading_items (slug, title, source_type, author, url, edition_note, summary, why_it_matters, key_takeaways, how_to_use_it, difficulty, last_verified_at, status)
values ($c$gmc-decision-making-consent$c$, $c$Decision Making and Consent$c$, $c$gmc$c$::interview.reading_source_type, $c$General Medical Council$c$, $c$https://www.gmc-uk.org/professional-standards/the-professional-standards/decision-making-and-consent$c$, $c$In force since 9 November 2020.$c$, $c$This GMC guidance sets out how doctors should support patients to make decisions about their care. It is built around seven principles, the heart of which is that decision-making is a dialogue: patients have the right to be involved, and doctors should find out what matters to each person so they can share information that is relevant to them. That includes the option of doing nothing, and the risks of harm and potential benefits of each option. Doctors must start from the presumption that adults have capacity, support people to make their own decisions wherever possible, and respect a capable patient's decision even if the doctor disagrees. The guidance reflects the Montgomery judgment: the question is not what a responsible body of doctors would disclose, but what this particular patient would want to know. It also covers consent for children and young people, patients who lack capacity, and situations where time is short.$c$, $c$Consent is one of the most common ethics themes at interview. Knowing that it is a two-way process — not a signature on a form — is a key marker of insight.$c$, $c$["Consent is a process of shared decision-making, not a form.","Doctors should find out what matters to the patient and tailor information accordingly.","Material risks are judged from the patient's perspective (reflecting Montgomery, 2015).","Adults are presumed to have capacity; a capable patient's refusal must be respected.","The option of taking no action should always be discussed."]$c$::jsonb, $c$Use in refusal-of-treatment and information-sharing scenarios: 'GMC guidance and the Montgomery ruling mean I'd need to explain the risks that matter to her, not just those a doctor thinks are important.'$c$, 3, $c$2026-09-29$c$, 'published')
on conflict (slug) do update set title = excluded.title, source_type = excluded.source_type, author = excluded.author, url = excluded.url, edition_note = excluded.edition_note, summary = excluded.summary, why_it_matters = excluded.why_it_matters, key_takeaways = excluded.key_takeaways, how_to_use_it = excluded.how_to_use_it, difficulty = excluded.difficulty, last_verified_at = excluded.last_verified_at, status = excluded.status;
delete from interview.reading_item_categories where reading_item_id = (select id from interview.reading_items where slug = $c$gmc-decision-making-consent$c$);
insert into interview.reading_item_categories (reading_item_id, category_id) values ((select id from interview.reading_items where slug = $c$gmc-decision-making-consent$c$), (select id from interview.categories where slug = $c$ethics-professionalism$c$));
insert into interview.reading_items (slug, title, source_type, author, url, edition_note, summary, why_it_matters, key_takeaways, how_to_use_it, difficulty, last_verified_at, status)
values ($c$gmc-confidentiality$c$, $c$Confidentiality: Good Practice in Handling Patient Information$c$, $c$gmc$c$::interview.reading_source_type, $c$General Medical Council$c$, $c$https://www.gmc-uk.org/professional-standards/the-professional-standards/confidentiality$c$, $c$Core guidance published 2017 with supplementary guidance, including on reporting concerns to the DVLA.$c$, $c$Trust depends on patients being confident that what they tell doctors will be kept private, and this guidance explains when confidentiality can and cannot be set aside. Confidentiality is described as important but not absolute. Doctors may disclose personal information if the patient consents, if the law requires it (for example, notifying certain infectious diseases or responding to a court order), or if disclosure is justified in the public interest — typically where failing to disclose could expose others to a risk of death or serious harm. Any disclosure should be the minimum necessary, and wherever practical the patient should be told first. Supplementary guidance applies these principles to specific situations, such as a patient who continues to drive when medically unfit: the doctor should first try to persuade them to stop and inform the DVLA themselves, and may disclose to the DVLA if they do not, after telling the patient they intend to do so.$c$, $c$Confidentiality dilemmas — driving, safeguarding, infectious disease, a teenager's secret — are staple interview stations. The key is showing confidentiality is a strong default with defined exceptions.$c$, $c$["Confidentiality is essential to trust but is not absolute.","Disclosure routes: consent, legal requirement, or public interest (risk of death or serious harm to others).","Disclose the minimum necessary, to the right person, and tell the patient where practicable.","For unfit drivers: persuade first; disclose to the DVLA if the patient won't, informing them first."]$c$::jsonb, $c$Frame confidentiality answers as 'strong default, defined exceptions', then walk through persuasion before disclosure.$c$, 3, $c$2026-09-29$c$, 'published')
