insert into interview.interviewer_personas (slug, name, style, description, follow_up_style, prompt_key, affinity_university_id, sort_order, is_active)
values ($c$dr-warm$c$, $c$Dr Warm$c$, $c$warm$c$::interview.persona_style, $c$Friendly and encouraging. Puts you at ease and gives gentle, supportive reactions — a good place to start and build confidence.$c$, $c$Open, encouraging follow-ups that invite you to expand ('Tell me more about that — what did you notice?').$c$, $c$warm-v1$c$, null, 0, true)
on conflict (slug) do update set name = excluded.name, style = excluded.style, description = excluded.description, follow_up_style = excluded.follow_up_style, prompt_key = excluded.prompt_key, affinity_university_id = excluded.affinity_university_id, sort_order = excluded.sort_order, is_active = excluded.is_active;
insert into interview.interviewer_personas (slug, name, style, description, follow_up_style, prompt_key, affinity_university_id, sort_order, is_active)
values ($c$dr-neutral$c$, $c$Dr Neutral$c$, $c$neutral$c$::interview.persona_style, $c$Professional and impassive, like a real MMI assessor. Gives no feedback during the interview, so you practise performing without reassurance.$c$, $c$Brief, scripted follow-ups that probe depth without signalling whether you are right.$c$, $c$neutral-v1$c$, (select id from interview.universities where slug = $c$imperial$c$), 1, true)
