insert into interview.interviewer_personas (slug, name, style, description, follow_up_style, prompt_key, affinity_university_id, sort_order, is_active)
values ($c$dr-probing$c$, $c$Dr Probing$c$, $c$probing$c$::interview.persona_style, $c$Challenges every answer, Oxbridge-style. Pushes your assumptions and asks 'why?' repeatedly to test how you reason under pressure — never unkind, always rigorous.$c$, $c$Persistent 'why?', 'what if?' and 'are you sure?' questions; offers counter-examples and hints to see if you can adapt.$c$, $c$probing-v1$c$, (select id from interview.universities where slug = $c$oxford$c$), 2, true)
