insert into interview.interviewer_personas (slug, name, style, description, follow_up_style, prompt_key, affinity_university_id, sort_order, is_active)
values ($c$dr-clinical$c$, $c$Dr Clinical$c$, $c$clinical$c$::interview.persona_style, $c$Science-heavy. Focuses on applying biology and chemistry to the body and to clinical problems, following up on the reasoning behind each step.$c$, $c$Follow-ups that drill into mechanisms: 'What's happening at the cellular level?', 'How would you test that?'$c$, $c$clinical-v1$c$, (select id from interview.universities where slug = $c$cambridge$c$), 3, true)
